// The clips behind the charts (clips.html): one table per clip set, generated by
// nceval.site from the clip sets and exclusion lists the charts use. Data: data/clips.json.
import { control, el, fail, loadData, segmented, sources, table } from './common.js';

const SETS = {
  fresh: 'Held-out, fresh',
  heldout: 'Held-out, all',
  dev: 'Development',
  ctc: 'AOM CTC low delay (Fixed QP)',
};
const state = { set: new URLSearchParams(window.location.search).get('set') || 'fresh' };

function render(data, root) {
  const clips = data.sets[state.set] || [];
  const n = data.counts[state.set];
  root.querySelector('.summary').textContent = `${SETS[state.set]}: ${n.clips} clips, ${n.scored} scored${n.left_out ? `, ${n.left_out} left out for every encoder (no reliable rate overlap with the zero line)` : ''}.`;
  root.querySelector('.clip-table').replaceChildren(table([
    { label: 'Clip', cell: (c) => c.name },
    { label: 'Source collection', cell: (c) => c.dataset },
    { label: 'Resolution', cell: (c) => `${c.width}×${c.height}` },
    { label: 'fps', num: true, cell: (c) => String(c.fps) },
    { label: 'Start frame', num: true, cell: (c) => String(c.start_frame) },
    { label: 'Frames', num: true, cell: (c) => String(c.frames) },
    { label: 'Class', cell: (c) => c.class },
    { label: 'Scoring', cell: (c) => (c.scored ? 'scored' : `left out${c.left_out_reason ? `: ${c.left_out_reason}` : ''}`) },
  ], clips, (c) => (c.scored ? '' : 'dim')), sources(data.source));
}

async function main() {
  const root = document.getElementById('clips');
  try {
    const data = await loadData('clips');
    if (!data.sets[state.set]) state.set = 'fresh';
    root.querySelector('.controls').append(control('Clip set', segmented('Clip set',
      Object.entries(SETS).map(([value, label]) => ({ value, label })), state.set,
      (v) => { state.set = v; render(data, root); })));
    render(data, root);
  } catch (error) {
    fail(root, error);
  }
}

main();
